properties.query:
let windowSize = 30m;

// S120: Failsafe Blocked
let S120 =
    UAVOpmode_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'failsafe_blocked'
    | extend Stage = 'S120', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

// S112: Forced RTB
let S112 =
    UAVOpmode_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'rtb_forced'
    | extend Stage = 'S112', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

// S126: Landing-Phase Attack
let S126 =
    UAVOpmode_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'landing_phase_attack'
    | extend Stage = 'S126', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

union S120, S112, S126
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by UAVId
| where StageCount >= 2
| extend CampaignType = "C32_착륙강제_페일세이프차단_RTB강제_이착륙위상공격"
| extend StepSummary = strcat("Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, UAVId, StagesSeen, StageCount, CampaignType, StepSummary, Severity
